          "fields": [
            {
              "id": "expenseid",
              "label": "Expense ID",
              "type": "string",
              "direction": "input",
              "binding": "vars.fetchExpense1.output.expenseId"
            },
            {
              "id": "amount",
              "label": "Amount",
              "type": "number",
              "direction": "input",
              "binding": "vars.fetchExpense1.output.amount"
            },
            {
              "id": "submitter",
              "label": "Submitted By",
              "type": "string",
              "direction": "input",
              "binding": "vars.fetchExpense1.output.submitterName"
            },
            {
              "id": "category",
              "label": "Category",
              "type": "string",
              "direction": "input",
              "binding": "vars.fetchExpense1.output.category"
            },
            {
              "id": "rejectionreason",
              "label": "Rejection Reason",
              "type": "string",
              "direction": "output",
              "variable": "vars.rejectionReason",
              "required": false
            }
          ],
          "outcomes": [
            {
              "id": "approve",
              "name": "Approve",
              "type": "string",
              "isPrimary": true,
              "action": "Continue"
            },
            {
              "id": "reject",
              "name": "Reject",
              "type": "string",
              "isPrimary": false,
              "action": "Continue"
            }
          ]
        }
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Task result data",
          "source": "=result",
          "var": "output",
          "properties": {
            "rejectionreason": { "type": "string" },
            "Action": { "type": "string", "enum": ["Approve", "Reject"], "default": "Approve" }
          }
        },
        "status": {
          "type": "string",
          "description": "Task completion status",
          "source": "=result.Action",
          "var": "status",
          "enum": ["Approve", "Reject"],
          "default": "Approve"
        }
      }
    },
    {
      "id": "logOutcome1",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Log Outcome"
      },
      "inputs": {
        "script": "// Read manager's decision and optional rejection reason\nvar decision = $vars.managerReview1.status;\nvar isApproved = decision === \"Approve\";\nvar rejectionReason = $vars.managerReview1.output.rejectionreason;\n\nreturn {\n  expenseId: $vars.fetchExpense1.output.expenseId,\n  submitterName: $vars.fetchExpense1.output.submitterName,\n  amount: $vars.fetchExpense1.output.amount,\n  category: $vars.fetchExpense1.output.category,\n  decision: decision,\n  approved: isApproved,\n  rejectionReason: isApproved ? null : rejectionReason,\n  logMessage: isApproved\n    ? \"Expense \" + $vars.fetchExpense1.output.expenseId + \" APPROVED for \" + $vars.fetchExpense1.output.submitterName + \" (\" + $vars.fetchExpense1.output.category + \", $\" + $vars.fetchExpense1.output.amount + \")\"\n    : \"Expense \" + $vars.fetchExpense1.output.expenseId + \" REJECTED for \" + $vars.fetchExpense1.output.submitterName + \" — Reason: \" + rejectionReason\n};"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=result.Error",
          "var": "error"
        }
      }
    },
    {
      "id": "end1",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "Done"
      },
      "inputs": {}
    }
  ],
